toolArgs.file_text:
.catalog-filters {
    padding: 1.25rem;
    background: #f8f9fa;
    border-radius: 8px;
    border: 1px solid #e0e0e0;
}

.catalog-filters h4 {
    margin: 0 0 1rem;
    font-size: 1.15rem;
    color: #333;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h5 {
    margin: 0 0 0.5rem;
    font-size: 0.9rem;
    color: #555;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.filter-placeholder {
    color: #999;
    font-size: 0.9rem;
    font-style: italic;
}

.price-inputs {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.price-inputs input {
    width: 80px;
    padding: 0.4rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 6px;
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
    cursor: pointer;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    padding: 0.5rem 1rem;
    border: 1px solid #6c757d;
    border-radius: 6px;
    background: transparent;
    color: #6c757d;
    font-weight: 600;
    cursor: pointer;
}

.btn-clear:hover {
    background: #6c757d;
    color: #fff;
}

